def two_sum(nums, target):
    # TODO: implement two sum
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen:
            return [seen[diff], i]
        seen[num] = i
    return []

def main():
    nums = list(map(int, input().split()))
    target = int(input().strip())
    result = two_sum(nums, target)
    print(f"{result[0]} {result[1]}")

if __name__ == '__main__':
    main()
